'use strict';
const E=window.RabEngine, KEY='rab3-demo-v1';
let state=E.fresh();try{const saved=JSON.parse(localStorage.getItem(KEY)||'null');if(saved?.version===1)state={...state,...saved};}catch{}
let page=location.hash.slice(1)||'today',setupStep=0,mapTab='coverage',mapSelection='companion',modalReturn=null,toastTimer;
const app=document.getElementById('app'),overlay=document.getElementById('overlay');
function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function save(){try{const value=E.clone(state);if(!state.memory)value.messages=[];localStorage.setItem(KEY,JSON.stringify(value));}catch{toast('This browser could not save your demo. Your current session still works.');}}
function fmt(d){if(!d)return 'Not recorded';return new Date(d+'T12:00:00Z').toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric'});}
function cash(v){return 'AED '+Number(v).toLocaleString('en-AE');}
function btn(label,action,arg='',kind=''){return `<button class="button ${kind}" data-action="${action}" data-arg="${esc(arg)}" type="button">${label}</button>`;}
function tag(t,kind=''){return `<span class="tag ${kind}">${esc(t)}</span>`;}
function buddy(cls='buddy'){return `<img class="${cls}" data-color="${esc(state.color)}" src="assets/companion.webp" alt="${esc(state.buddy)}, your small ivory and teal robot companion">`;}
function toast(msg){clearTimeout(toastTimer);const t=document.getElementById('toast');t.textContent=msg;t.className='toast-show';toastTimer=setTimeout(()=>{t.textContent='';t.className='';},3800);}
function navigate(p){page=p;location.hash=p;render();window.scrollTo({top:0,behavior:'instant'});}
const navs=[['today','◌','My companion'],['chat','◍','Our conversation'],['journey','⌁','My journey'],['essentials','▤','My essentials'],['discover','✺','Discover'],['city','▦','City services'],['sharing','◇','What is shared'],['settings','☷','How we get along']];
function shell(content){return `<div class="shell"><aside class="sidebar"><a class="brand" href="#today" aria-label="Rab3 home"><span class="wordmark">Rab3</span><i class="brand-dot"></i><span class="arabic" lang="ar">ربع</span></a><nav class="nav" aria-label="Main navigation">${navs.map(([p,i,t],n)=>`${n===5?'<div class="nav-label">Connected, separately</div>':''}<button type="button" data-action="nav" data-arg="${p}" class="${page===p?'active':''}" ${page===p?'aria-current="page"':''}><span class="ico" aria-hidden="true">${i}</span>${t}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="mini-buddy">${buddy('companion-tiny')}<div><strong>${esc(state.buddy)}</strong><small class="muted">Your own kind of company</small></div></div><nav class="nav" aria-label="Prototype views"><button data-action="nav" data-arg="blueprint" class="${page==='blueprint'?'active':''}"><span class="ico">⌘</span>The bigger picture</button><button data-action="nav" data-arg="pilot" class="${page==='pilot'?'active':''}"><span class="ico">▥</span>Pilot overview</button></nav><button class="text-button" data-action="about">About this prototype</button></div></aside><div class="workspace"><header class="topbar"><div class="topbar-left"><span class="mobile-brand">Rab3</span><span class="crumb">Abu Dhabi <span class="muted">/</span> ${['city','pilot'].includes(page)?'City & ecosystem':'Your personal space'}</span><span class="pill private">${page==='city'?'Separate service space':'Device-local demo'}</span></div><div class="topbar-right"><button class="pill demo" data-action="tour">Walk through Rab3</button><button class="avatar" data-action="nav" data-arg="settings" aria-label="Your preferences">${esc(state.name.charAt(0).toUpperCase())}</button></div></header><main class="content" id="main">${content}<footer class="app-footer"><span>Rab3 · Interactive prototype</span><div><button class="text-button" data-action="nav" data-arg="blueprint">Infrastructure</button><button class="text-button" data-action="nav" data-arg="pilot">Pilot view</button><button class="text-button" data-action="about">What works here</button></div></footer></main></div></div>`;}
function pageHead(title,sub,extra=''){return `<div class="page-head"><div><span class="eyebrow muted">${['city','pilot'].includes(page)?'Connected city':'Your Rab3'}</span><h1 style="margin-top:10px">${title}</h1>${sub?`<p>${sub}</p>`:''}</div>${extra}</div>`;}
function taskCard(t){return `<article class="card ${t.priority>=90?'urgent':''}"><div class="card-title"><span class="domain-icon" aria-hidden="true">${t.icon}</span>${tag(t.domain,t.priority>=90?'amber':'')}</div><h3>${t.title}</h3><p>${esc(t.desc)}</p><div class="meta">${esc(t.source)}</div><button type="button" class="link" data-action="task" data-arg="${t.id}">${t.id==='salary'&&state.income==='unknown'?'Update me':'Let’s sort this out'}</button></article>`;}
function composer(){return `<form class="composer" id="chat-form"><label class="skip" for="message-input">Talk to ${esc(state.buddy)}</label><textarea id="message-input" name="message" rows="1" placeholder="Talk to ${esc(state.buddy)}…" maxlength="1200" required></textarea><button type="submit">Send</button></form><div class="fine" style="margin-top:8px">Interactive conversation demo · responses follow the demonstration scenarios · nothing is sent externally</div>`;}
function today(){const g=E.greeting(state),p=E.priorities(state);return `<div class="row" style="margin-bottom:20px"><span class="eyebrow muted">${fmt(E.dateAt(state.day))} · Demonstration day ${state.day+1}</span>${btn('Something changed','changes','','ghost small')}</div><section class="companion-stage" data-mood="${g.mood}"><div class="stage-copy"><span class="eyebrow">${esc(state.buddy)} · Your companion</span><h1>${esc(g.title)}</h1><p>${esc(g.body)}</p><div class="actions">${btn(state.paused?'Talk to me':'Let’s start here',state.paused?'nav':'task',state.paused?'chat':p[0]?.id||'community','primary')}${btn(state.paused?'Bring check-ins back':'Give me a little space','pause','','ghost')}</div></div><div class="buddy-wrap">${buddy()}<span class="buddy-label">${state.paused?'Quietly here':'Alongside you'}</span></div></section>${composer()}<div class="chips">${['My salary hasn’t arrived','I’m feeling overwhelmed','Find my kind of people'].map(x=>`<button class="chip" data-action="say" data-arg="${esc(x)}">${x}</button>`).join('')}</div><div class="section-head"><h2>${state.feeling==='Overwhelmed'?'A smaller day, on purpose':'A few things worth your attention'}</h2><button class="text-button" data-action="nav" data-arg="journey">Your whole journey</button></div><div class="cards">${p.length?p.map(taskCard).join(''):'<div class="empty"><h3>You have some breathing room.</h3><p>Nothing needs a new nudge right now.</p></div>'}</div><div class="strip"><div><span class="eyebrow muted">A little check-in</span><p style="margin-top:5px">How is today feeling?</p><div class="feeling-row">${['Steady','Excited','Overwhelmed','Need space'].map(x=>`<button class="${state.feeling===x?'selected':''}" data-action="feeling" data-arg="${x}">${x}</button>`).join('')}</div></div><div class="fine" style="max-width:240px">Your answer shapes the pace of support. It stays in this browser’s companion space.</div></div>${state.revisions.length?`<div class="section-head"><h2>What we adjusted together</h2>${btn('See changes','history','','small ghost')}</div><div class="card"><h3>${esc(state.revisions[0].title)}</h3><p>${esc(state.revisions[0].detail)}</p></div>`:''}`;}
function actionLabel(a){return {money:'Review my breathing room',sharing:'See what is shared',discover:'Explore with me',city:'Open city services',wellbeing:'Make space for support',salary:'Prepare a follow-up',housing:'Look at my next stay',medical:'Check my appointment',community:'Find a first connection',transport:'Explore my commute',budget:'Review commitments'}[a]||'Open this step';}
function chat(){return `${pageHead('A familiar place to talk.',`${esc(state.buddy)} remembers what you choose to share—and adjusts when you correct it.`,btn('Something changed','changes','','ghost'))}<div class="chat-layout"><div class="chat-box"><div class="messages" id="messages">${state.messages.length?state.messages.map(m=>`<div class="message ${m.role}"><span class="sender">${m.role==='user'?esc(state.name):esc(state.buddy)}</span><div class="reply-body">${esc(m.text)}</div>${m.actions?.length?`<div class="actions">${m.actions.map(a=>btn(actionLabel(a),'chat-action',a,'small')).join('')}</div>`:''}</div>`).join(''):`<div class="message assistant"><span class="sender">${esc(state.buddy)}</span><div class="reply-body">You don’t have to arrive with everything figured out. Tell me what’s on your mind, or let’s pick up one of the loose ends together.</div></div>`}</div>${composer()}<div class="chips">${['What matters today?','My appointment is confirmed','I need some space','What is shared?'].map(x=>`<button class="chip" data-action="say" data-arg="${esc(x)}">${x}</button>`).join('')}</div></div><aside class="chat-side">${buddy()}<h3>${esc(state.buddy)}</h3><p class="small muted" style="margin:7px 0 20px">${esc(state.style)} company.<br>Your pace, your way.</p><div class="card"><span class="eyebrow muted">What I’m working with</span><div class="list-row"><div><strong>${esc(state.workplace)}</strong><p>Your usual workplace</p></div></div><div class="list-row"><div><strong>${esc(state.hours)}</strong><p>Your working hours</p></div></div><div class="list-row"><div><strong>${esc(state.feeling)}</strong><p>How you said today feels</p></div></div>${btn('Correct what I remember','memory','','small ghost')}</div></aside></div>`;}
function journey(){const t=E.tasks(state),done=t.filter(x=>x.status==='completed').length;return `${pageHead('A life taking shape.','Your first 90 days are a beginning. This path keeps changing with you.',btn('What changed?','history','','ghost'))}<div class="two-col"><div><div class="row"><span class="small">${done} of ${t.length} demonstration milestones recorded</span><span class="small muted">Day ${Math.max(1,Math.round((new Date(E.dateAt(state.day))-new Date(state.arrival))/86400000)+1)}</span></div><div class="progress-track"><div class="progress-fill" style="width:${done/t.length*100}%"></div></div><div class="timeline">${['First days','Settle in','Find your rhythm','Build your future'].map(phase=>`<div class="phase">${phase}</div>${t.filter(x=>x.phase===phase).map(x=>`<div class="timeline-item ${x.status}"><div class="card"><div>${tag(x.status==='completed'?'Recorded complete':x.snoozed?'Taking a pause':x.status==='future'?'Later, together':'Next step',x.status==='future'?'blue':'')}<h3>${x.title}</h3><p>${esc(x.desc)}</p><div class="fine" style="margin-top:8px">${fmt(x.date)} · ${esc(x.source)}</div></div>${btn(x.status==='future'?'Explore the idea':'Open','task',x.id,'small ghost')}</div></div>`).join('')}`).join('')}</div></div><aside class="stack"><div class="card accent-body"><span class="eyebrow muted">The connections matter</span><h2 style="margin:12px 0">One update can change a whole week.</h2><p>An income delay can reshape housing choices and spending. A confirmed appointment closes one loose end without changing completed work.</p>${btn('Try a change','changes','','primary')}</div><div class="card"><h3>Your wider life</h3><p>Every domain belongs to the bigger picture.</p><div class="overview-domains" style="margin-top:15px">${['Residency','Employment','Home','Transport','Money','Health','Family','Belonging','Learning','Business'].map(x=>`<span>${x}</span>`).join('')}</div>${btn('See the infrastructure','nav','blueprint','small ghost')}</div></aside></div>`;}
function essentials(){return `${pageHead('The things worth remembering.','Dates and circumstances you can correct at any time.',btn('What I remember','memory','','ghost'))}<div class="two-col"><form id="essentials-form" class="card"><h2>Your practical details</h2><p class="small muted" style="margin:8px 0 22px">Fictional sample details. No documents or identity numbers are needed.</p><div class="form-grid">${field('Name','name',state.name)}${field('Arrival date','arrival',state.arrival,'date')}${field('Temporary stay ends','homeEnd',state.homeEnd,'date')}${field('Expected salary date','salaryDate',state.salaryDate,'date')}${field('Recorded visa expiry','visaExpiry',state.visaExpiry,'date')}${field('Workplace','workplace',state.workplace)}${field('Working hours','hours',state.hours)}${field('Monthly housing budget (AED)','budget',state.budget,'number')}${field('Expected monthly salary (AED)','salary',state.salary,'number')}${field('Money currently available (AED)','available',state.available,'number')}${field('Known upcoming commitments (AED)','essential',state.essential,'number')}${field('Preferred support budget (AED)','wellbeingBudget',state.wellbeingBudget,'number')}</div><button class="button primary" type="submit">Update our understanding</button></form><aside class="stack"><div class="card"><div class="card-title"><h3>Recorded dates</h3>${tag('Your entries')}</div><div class="list-row"><div><strong>Temporary accommodation</strong><p>${fmt(state.homeEnd)} · ${E.daysUntil(state.homeEnd,state.day)} days from demo date</p></div></div><div class="list-row"><div><strong>Visa expiry</strong><p>${fmt(state.visaExpiry)} · ${E.daysUntil(state.visaExpiry,state.day)} days from demo date</p></div></div><div class="notice" style="margin-top:15px">A reminder based on a date you entered is not a check of legal status or eligibility.</div></div><div class="card"><h3>Known money, clearly separated</h3><div class="list-row"><span>Available</span><strong>${cash(state.available)}</strong></div><div class="list-row"><span>Known commitments</span><strong>${cash(state.essential)}</strong></div><div class="list-row"><span>Difference</span><strong>${cash(state.available-state.essential)}</strong></div><p>Before unrecorded costs. No bank or payroll data is connected.</p>${btn('Think this through','money','','small')}</div><div class="card"><h3>What is not here</h3><p>No passport scans, medical records, account credentials or identity numbers. The prototype keeps only the demonstration details you enter on this device.</p></div></aside></div>`;}
function field(label,name,value,type='text'){return `<div class="field"><label for="f-${name}">${label}</label><input id="f-${name}" name="${name}" type="${type}" value="${esc(value)}" ${type==='number'?'min="0" max="10000000" step="1"':'maxlength="120"'} required></div>`;}
const discoveries=[{id:'outdoors',title:'Find a small outdoor ritual',label:'Outdoors',icon:'≋',body:'An easy first walk can be enough. Explore the city’s places and check conditions before heading out.',reason:'A low-commitment idea for your first weeks.',url:'https://visitabudhabi.ae/en/campaign/my-abu-dhabi-experience',source:'Experience Abu Dhabi'}, {id:'culture',title:'A city beyond the commute',label:'Culture',icon:'✺',body:'Look through official cultural experiences and find something that catches your attention.',reason:'Make room for curiosity alongside the practicalities.',url:'https://visitabudhabi.ae/en/book-your-trip',source:'Experience Abu Dhabi'}, {id:'people',title:'Your first shared interest',label:'People',icon:'◎',body:'Start with an interest, not a passport. Choose music, movement or learning as your conversation starter.',reason:'Based on the interests you choose to share.',url:'https://visitabudhabi.ae/en/sitemap',source:'Experience Abu Dhabi'}, {id:'commute',title:'Try the everyday route',label:'Transport',icon:'▥',body:'Explore public transport information before committing to a car or a longer rental.',reason:'Useful while your home and work routine are still settling.',url:'https://admobility.gov.ae/en/pb-bus-service/',source:'Abu Dhabi Mobility'}];
function discover(){return `${pageHead('Find a little of yourself here.','Interests, places and possibilities. You set the pace.')}<div class="card" style="margin-bottom:22px"><div class="row"><h3>What feels like you?</h3><span class="small muted">Choose a few</span></div><div class="chips">${['Outdoors','Music','Culture','Food','Learning','Fitness','Founders','Volunteering'].map(x=>`<button class="chip ${state.interests.includes(x)?'selected':''}" data-action="interest" data-arg="${x}" aria-pressed="${state.interests.includes(x)}">${x}</button>`).join('')}</div></div><div class="two-col">${discoveries.map(d=>`<article class="card"><div class="card-title"><span class="domain-icon">${d.icon}</span>${tag(d.label)}</div><h2>${d.title}</h2><p>${d.body}</p><div class="notice" style="margin-top:18px">${d.id==='people'?`Your interests: ${esc(state.interests.join(', ')||'choose above')}. `:''}${d.reason}</div><div class="actions"><a class="button primary" href="${d.url}" target="_blank" rel="noopener noreferrer">Explore the official guide</a>${btn(state.saved.includes(d.id)?'Saved':'Keep this idea','save-idea',d.id,'ghost')}</div><div class="fine" style="margin-top:13px">${d.source} · public guide checked 2 Oct 2026 · prices, schedules and availability must be checked with the source</div></article>`).join('')}</div><div class="strip"><div><h3>Belonging happens with people.</h3><p>Your companion helps you take a first step toward real connections.</p></div>${btn('Talk it through','say','Find my kind of people','ghost')}</div>`;}
const services=[{title:'Government services',source:'Government of Abu Dhabi',body:'Find the official route for public services and TAMM.',url:'https://www.abudhabi.gov.ae/en/services',icon:'▦'}, {title:'Getting around',source:'Abu Dhabi Mobility',body:'Explore public transport services and official information.',url:'https://admobility.gov.ae/en/pb-bus-service/',icon:'≋'}, {title:'Healthcare directory',source:'Department of Health',body:'Find official tools for looking up healthcare facilities.',url:'https://www.doh.gov.ae/en/resources/Lists%20and%20Tools',icon:'✧'}, {title:'Healthcare appointments',source:'Sahatna · Department of Health',body:'Explore the official health platform and its appointment services.',url:'https://sahatna-app.doh.gov.ae/en/',icon:'♡'}];
function city(){return `${pageHead('Your city. Connected on your terms.','Official destinations have their own records. Your personal conversations stay separate.')}<div class="notice city" style="margin-bottom:24px">No government, employer, bank or healthcare account is connected. Links open official websites. The handoff below is a labelled simulation and sends nothing.</div><div class="two-col">${services.map(s=>`<article class="card"><div class="card-title"><span class="domain-icon">${s.icon}</span>${tag('Official public link','blue')}</div><h2>${s.title}</h2><p>${s.body}</p><div class="actions"><a class="button" href="${s.url}" rel="noopener noreferrer" target="_blank">Visit ${s.source}</a></div><div class="fine" style="margin-top:14px">Public source checked 2 Oct 2026 · no partnership or integration implied</div></article>`).join('')}</div><div class="section-head"><h2>A careful connection</h2>${tag('Simulated')}</div><div class="card"><div class="row"><div><h3>Appointment status, without your private conversation</h3><p>See how a single service update could help your companion keep the journey moving.</p></div>${btn('See the handoff','handoff','','primary')}</div><div class="domain-pair">${tag('Name + appointment reference','blue')}${tag('One named recipient','blue')}${tag('No conversation history')}</div></div>`;}
function sharing(){return `${pageHead('Yours means understandable.','See the boundary, the details, and the choices.')}<div class="two-col"><div class="card accent-body"><span class="eyebrow">My companion</span><h2 style="margin:12px 0">Your personal space</h2><p>Conversations, preferences, feelings and goals support you here. In this prototype, they are stored in this browser only.</p><div class="divider"></div><div class="list-row"><div><strong>What I remember</strong><p>See and correct your practical details and preferences.</p></div>${btn('View','memory','','small')}</div><div class="list-row"><div><strong>Personal conversations</strong><p>${state.messages.filter(m=>m.role==='user').length} messages from you in this demo.</p></div>${btn('Clear','clear-chat','','small ghost')}</div></div><div class="card"><span class="eyebrow">City services</span><h2 style="margin:12px 0">A separate relationship</h2><p>In the proposed production design, a service would receive only the fields required for a named purpose. Receiving a status would not grant access to your personal memory.</p><div class="divider"></div><div class="notice city">The real-world architecture, access controls and operating agreements still need implementation and review. This screen is not a claim of deployed government privacy infrastructure.</div></div></div><div class="section-head"><h2>What has been shared</h2>${btn('Try a simulated handoff','handoff','','small')}</div>${state.receipts.length?state.receipts.map(r=>`<div class="card" style="margin-bottom:14px"><div class="row"><h3>${esc(r.recipient)}</h3>${tag('Simulation · nothing sent','blue')}</div><p>Purpose: appointment status update.</p><div class="list-row"><span>Included</span><strong>${esc(r.fields.join(', '))}</strong></div><div class="list-row"><span>Excluded</span><strong>Conversation, feelings, income and goals</strong></div><div class="fine" style="margin-top:12px">${fmt(r.date)} · ${r.disconnected?'Future access disconnected':'Connection allowed for this simulated purpose'}</div>${!r.disconnected?btn('Disconnect future updates','disconnect',r.id,'small ghost'):''}</div>`).join(''):'<div class="empty"><h3>Nothing has been sent.</h3><p>Your companion can be useful without exposing the rest of your life.</p></div>'}<div class="strip"><div><h3>Personal support is a choice.</h3><p>Using an official service should not require private wellbeing conversations or personal memory.</p></div>${btn('How we get along','nav','settings','ghost')}</div>`;}
function settings(){return `${pageHead('Make this feel like you.','A familiar name. The right tone. Enough space.')}<form id="settings-form"><div class="two-col"><div class="stack"><div class="card"><h2>Your companion</h2><div class="row" style="margin:15px 0">${buddy('companion-tiny')}<span class="small muted">Rab3 is the product. This name is yours.</span></div>${field('What do you call your companion?','buddy',state.buddy)}<div class="field"><label for="style">How should we talk?</label><select id="style" name="style">${['Warm','Direct','Playful'].map(x=>`<option ${state.style===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label for="color">A colour that feels right</label><select id="color" name="color">${[['teal','Palm green'],['blue','Coastal blue'],['clay','Warm clay']].map(([v,t])=>`<option value="${v}" ${state.color===v?'selected':''}>${t}</option>`).join('')}</select></div><p class="fine">Your companion stays an AI character, even if its name carries a personal meaning.</p></div><div class="card"><h2>The right amount of company</h2><div class="field" style="margin-top:18px"><label for="pace">Your preferred pace</label><select name="pace" id="pace">${['Gentle','Balanced','More involved'].map(x=>`<option ${state.pace===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="form-grid">${field('Quiet time starts','quietStart',state.quietStart,'time')}${field('Quiet time ends','quietEnd',state.quietEnd,'time')}</div><label class="toggle-row"><div><strong>Useful check-ins</strong><p>Speak first when dates or reported changes matter.</p></div><input type="checkbox" name="reminders" ${state.reminders?'checked':''}></label><label class="toggle-row"><div><strong>A little space for now</strong><p>Pause spontaneous conversation; direct chat stays available.</p></div><input type="checkbox" name="paused" ${state.paused?'checked':''}></label><p class="fine" style="margin-top:14px">The prototype checks dates while open. It does not send push notifications in the background.</p></div></div><div class="stack"><div class="card"><h2>What stays with us</h2><label class="toggle-row"><div><strong>Remember our conversations here</strong><p>Saved on this browser, not synced to another device.</p></div><input type="checkbox" name="memory" ${state.memory?'checked':''}></label><p>Practical profile details stay until you clear the demo. Turning conversation memory off clears saved chat history; new chat lasts only for the session.</p><div class="actions">${btn('See what I remember','memory','','small')}${btn('Clear conversation','clear-chat','','small ghost')}</div></div><div class="card"><h2>What a nudge should feel like</h2><div class="benefit"><h3>Relevant, not relentless</h3><p>One useful prompt, a clear reason, and room to say “not now.”</p></div><div class="benefit"><h3>Personal, not presumptive</h3><p>Your words and feedback guide the tone. Rab3 does not diagnose you or assign a personality score.</p></div><div class="benefit"><h3>You choose the real-world step</h3><p>A draft is just a draft until you decide to send it. This prototype cannot book or pay.</p></div></div><div class="card"><h3>Start fresh</h3><p>Delete this device’s demonstration profile and begin again.</p>${btn('Clear this demo','reset-confirm','','danger small')}</div></div></div><div class="actions"><button class="button primary" type="submit">That feels like me</button></div></form>`;}
const mapSets={coverage:[['The individual',['person']],['A companion you shape',['assistant','identity','behaviour','initiative','private','participation']],['Life domains',['residency','work','housing','transport','money','health','education','belong','growth','business']],['Shared intelligence',['memory','journey','events','planner','evidence','validate','actions','history']],['The boundary',['bridge','inbound','receipt']],['Connected ecosystem',['official','gov','employer','providers','communities']],['Operation and accountability',['ops','control','security','assurance','measure','reporting','operator']]],boundaries:[['Your private companion',['private','identity','memory','behaviour','initiative']],['Only selected exchanges',['bridge','control','receipt']],['Separate service records',['official','gov','employer','providers','inbound']],['Separate aggregate evaluation',['reporting','sponsor','measure']],['Controls across both spaces',['participation','operator','security','assurance']]],prototype:[['Meet and shape your companion',['identity','behaviour','initiative']],['Experience',['screen1','screen2','screen3','screen4','screen5','screen6']],['Connected demonstration domains',['work','housing','money','residency','belong']],['Build underneath',['memory','journey','events','planner','evidence','validate','actions','history','control']],['Visible boundary',['private','bridge','receipt','inbound','reporting']],['Delivery checks',['build','tests']]]};
function blueprint(){const selected=window.RAB_MAP[mapSelection]||window.RAB_MAP.assistant;return `${pageHead('One companion. A whole life around it.','The full infrastructure comes first. The demonstration is one connected part of it.',btn('The demonstration story','tour','','ghost'))}<div class="ui-tabs" role="tablist" aria-label="Infrastructure maps">${[['coverage','Full infrastructure'],['boundaries','Information boundaries'],['prototype','Prototype scope']].map(([id,title])=>`<button role="tab" aria-selected="${mapTab===id}" class="${mapTab===id?'active':''}" data-action="map-tab" data-arg="${id}">${title}</button>`).join('')}</div><div class="notice">Proposed architecture. Green left edges identify the planned prototype section; some capabilities are simplified or simulated here. Select a component for its implementation boundary.</div><div class="map-detail" aria-live="polite"><div class="row"><h2>${esc(selected.title)}</h2>${tag(selected.proto?'Prototype section':'Wider infrastructure')}</div><p>${esc(selected.purpose)}</p><div class="form-grid" style="margin-top:15px"><div><strong>Inputs</strong><p>${esc(selected.inputs)}</p></div><div><strong>Outputs</strong><p>${esc(selected.outputs)}</p></div></div><p><strong>Boundary:</strong> ${esc(selected.scope)}</p></div>${mapSets[mapTab].map(([label,ids],i)=>`${i?`<div class="map-bus">${mapTab==='boundaries'?'Scoped exchanges only · private memory is not an automatic shared record':'Context, evidence and scoped updates connect these layers'}</div>`:''}<section class="map-layer"><div class="map-label">${String(i+1).padStart(2,'0')} / ${label}</div><div class="map-nodes">${ids.map(id=>{const n=window.RAB_MAP[id];return `<button class="map-node ${n.proto?'included':''}" data-action="map-node" data-arg="${id}" aria-pressed="${id===mapSelection}">${n.title}</button>`;}).join('')}</div></section>`).join('')}`;}
function pilot(){return `${pageHead('Is life getting easier to navigate?','A separate institutional view of service outcomes—not personal conversations.')}<div class="notice city" style="margin-bottom:23px">Synthetic demonstration cohort: 40 fictional participants. These figures are illustrative, not observed results. No private conversation, emotional profile, diagnosis or named employer allegation is included.</div><div class="three-col"><div class="metric"><span class="small">Selected milestones completed</span><div class="amount">112 / 160</div><p>70% of four defined milestones across 40 sample participants</p></div><div class="metric"><span class="small">Median time to selected milestone</span><div class="amount">12 days</div><p>Illustrative; no comparison baseline established</p></div><div class="metric"><span class="small">Unresolved reported obstacles</span><div class="amount">18</div><p>Open issue records; not necessarily distinct participants</p></div></div><div class="two-col" style="margin-top:23px"><div class="card"><h2>Progress by milestone</h2><p>Sample completion counts, out of 40 participants.</p>${[['Arrival recorded',40],['Next accommodation arranged',28],['Appointment confirmed',25],['First community action',19]].map(([t,n])=>`<div class="bar-row"><span>${t}</span><div class="bar"><i style="width:${n/40*100}%"></i></div><strong>${n}/40</strong></div>`).join('')}</div><div class="card"><h2>Where the path becomes unclear</h2><p>Illustrative issue categories. A report is not a finding of fault.</p>${[['Appointment status unknown',8],['Housing timing unresolved',6],['Expected payment unconfirmed',4]].map(([t,n])=>`<div class="list-row"><span>${t}</span><strong>${n}</strong></div>`).join('')}<div class="notice" style="margin-top:17px">In a real pilot, define evidence standards and suppress small groups before reporting. Do not infer misconduct from missing data.</div></div></div><div class="section-head"><h2>What a real pilot would establish</h2></div><div class="three-col">${[['A defined outcome','One sponsor, one newcomer cohort, agreed settlement milestones and clear operating responsibilities.'],['A fair comparison','Baseline completion time, user effort and support demand. Report denominators, missing data and evidence quality.'],['A decision to expand','Demonstrated benefit, acceptable operating cost and an approved security and data-handling approach.']].map(([t,b])=>`<div class="card"><h3>${t}</h3><p>${b}</p></div>`).join('')}</div><div class="strip"><div><h3>What stays out of this view</h3><p>Private text, feelings, health history, individual personality profiles and personal relationship details.</p></div>${btn('Inspect the boundary','map-boundary','','ghost')}</div>`;}
function render(){document.body.dataset.color=state.color;if(!state.setup){app.innerHTML=onboarding();return;}const pages={today,chat,journey,essentials,discover,city,sharing,settings,blueprint,pilot};if(!pages[page])page='today';app.innerHTML=shell(pages[page]());if(page==='chat'){const m=document.getElementById('messages');m.scrollTop=m.scrollHeight;} }
function onboarding(){const copy=[['Let’s make this yours.','A name, a little character, and a familiar place to start.'],['A little about your new chapter.','Enough to be useful. The rest can unfold in conversation.'],['The right kind of company.','Choose how we get along. You can change everything later.']][setupStep];return `<main class="welcome" id="main"><section class="welcome-art"><a class="brand" href="#" aria-label="Rab3"><span class="wordmark">Rab3</span><i class="brand-dot"></i><span class="arabic" lang="ar">ربع</span></a><h1>A new city.<br>A familiar feeling.</h1><p>Make yourself at home, one small step at a time.</p><div class="buddy-wrap">${buddy()}</div><footer>YOUR COMPANION FOR ABU DHABI<br>Interactive prototype · fictional sample journey</footer></section><section class="welcome-form"><div class="step-dots" aria-label="Step ${setupStep+1} of 3">${[0,1,2].map(n=>`<i class="${n<=setupStep?'on':''}"></i>`).join('')}</div><span class="eyebrow muted">Meet your Rab3</span><h2>${copy[0]}</h2><p>${copy[1]}</p><form id="onboarding-form">${setupStep===0?`${field('What would you like to call your companion?','buddy',state.buddy)}<div class="small muted" style="margin:-5px 0 20px">A favourite name, a familiar word, or something entirely new.</div><div class="field"><label for="on-name">And what should it call you?</label><input id="on-name" name="name" value="${esc(state.name)}" maxlength="35" required></div><span class="small">A conversational style that feels right</span><div class="choice-row" style="margin-top:10px">${[['Warm','Thoughtful and reassuring'],['Direct','Clear and to the point'],['Playful','A little lightness']].map(([x,d])=>`<button type="button" class="choice ${state.style===x?'selected':''}" data-action="style" data-arg="${x}" aria-pressed="${state.style===x}"><strong>${x}</strong><small>${d}</small></button>`).join('')}</div>`:setupStep===1?`<div class="field"><label for="intent">What brings you to Abu Dhabi?</label><select name="intent" id="intent">${['A new chapter','A new job','Joining family','Building a business','Exploring the city'].map(x=>`<option ${state.intent===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="form-grid">${field('Arrival date','arrival',state.arrival,'date')}${field('Temporary stay ends','homeEnd',state.homeEnd,'date')}${field('Expected salary date','salaryDate',state.salaryDate,'date')}${field('Monthly housing budget (AED)','budget',state.budget,'number')}</div>${field('Usual working hours','hours',state.hours)}<div class="notice">The first build follows a newcomer’s settlement journey. Other intentions are captured as goals; their specialist journeys come later.</div>`:`<div class="field"><label for="on-pace">How involved should your companion be?</label><select name="pace" id="on-pace">${['Gentle','Balanced','More involved'].map(x=>`<option ${state.pace===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="form-grid">${field('Quiet time starts','quietStart',state.quietStart,'time')}${field('Quiet time ends','quietEnd',state.quietEnd,'time')}</div><label class="toggle-row"><div><strong>Remember our conversations on this device</strong><p>You can inspect, correct or clear them.</p></div><input name="memory" type="checkbox" ${state.memory?'checked':''}></label><label class="toggle-row"><div><strong>Speak first when something matters</strong><p>Useful nudges, with room to say “not now.”</p></div><input name="reminders" type="checkbox" ${state.reminders?'checked':''}></label><div class="notice" style="margin-top:20px">Your personal companion and city services are separate spaces. This prototype connects to no external accounts and sends no personal details.</div>`}<div class="welcome-footer">${setupStep>0?btn('Back','on-back','','ghost'):'<span></span>'}<button class="button primary" type="submit">${setupStep===2?'Meet '+esc(state.buddy):'Continue'}</button></div></form><button class="text-button" style="margin-top:23px" data-action="sample">Explore the complete sample journey</button><p class="fine" style="margin:10px 0 0">Use fictional information. Demo responses are scripted; an open-ended AI service is not connected.</p></section></main>`;}
function showModal(title,html,wide=false){modalReturn=document.activeElement;overlay.innerHTML=`<div class="modal-backdrop"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-head"><h2 id="modal-title">${title}</h2><button type="button" class="close" data-action="close" aria-label="Close dialog">×</button></div>${html}</section></div>`;overlay.querySelector('.close').focus();document.body.style.overflow='hidden';}
function closeModal(){overlay.innerHTML='';document.body.style.overflow='';if(modalReturn?.isConnected)modalReturn.focus();}
function openTask(id){const t=E.tasks(state).find(x=>x.id===id);if(!t){if(id==='wellbeing')openWellbeing();return;}if(id==='wellbeing'){openWellbeing();return;}if(id==='budget'){openMoney();return;}let content=`<div class="row">${tag(t.domain)}${tag(t.status==='completed'?'Recorded complete':t.snoozed?'Paused for now':t.status==='future'?'Later in the journey':'Needs a little attention',t.status==='completed'?'':'amber')}</div><p>${esc(t.desc)}</p><div class="card" style="margin:20px 0"><h3>Why this comes up</h3><p>${esc(t.why)}</p><div class="fine">Basis: ${esc(t.source)} · demonstration date ${fmt(E.dateAt(state.day))}</div></div>`;
if(id==='housing')content+=`<h3>Keep the next step manageable</h3><ol class="bullet"><li>Ask your current accommodation about an extension and its total cost.</li><li>Compare dates, cancellation terms and your route to ${esc(state.workplace)}.</li><li>Confirm the next stay before recording it here.</li></ol><div class="notice">No property inventory or live pricing is connected. ${state.income==='late'?'Your reported income delay makes avoiding unnecessary upfront commitments especially relevant.':'Your entered budget is '+cash(state.budget)+' per month.'}</div><div class="actions">${btn('Draft an extension request','draft','housing','primary')}${state.home!=='secured'?btn('My next stay is arranged','event','home-secured','ghost'):''}</div>`;
else if(id==='salary')content+=`<div class="notice">Expected date: ${fmt(state.salaryDate)}. Current status: ${state.income==='unknown'?'unknown':state.income==='late'?'reported outstanding by you':'reported received by you'}. No official finding about your employer is made.</div><div class="actions">${btn('Prepare a follow-up','draft','salary','primary')}${state.income!=='received'?btn('It has arrived','event','salary-received','ghost'):''}${state.income!=='late'?btn('Still outstanding','event','salary-late','ghost'):''}</div>`;
else if(id==='medical')content+=`<div class="notice">The person arranging the appointment is the source of confirmation. A recorded booking does not mean the appointment is attended or a residency process is approved.</div><div class="actions">${btn('Draft a friendly check-in','draft','medical','primary')}${state.medical!=='confirmed'?btn('I have confirmation','event','medical-confirmed','ghost'):''}${btn('See a connected example','handoff','','ghost')}</div>`;
else if(t.url)content+=`<a class="button primary" href="${t.url}" target="_blank" rel="noopener noreferrer">Open the official guide</a><div class="fine" style="margin-top:12px">Public source checked 2 Oct 2026. Confirm current prices, eligibility and availability directly.</div><div class="actions">${btn('I took this step','complete',id,'ghost')}</div>`;
else content+=`<p>${t.status==='future'?'This sits in the wider vision. We’ll return to it as your priorities take shape.':'You can record this milestone or keep exploring your journey.'}</p>${t.status!=='future'?btn('Record as complete','complete',id,'primary'):btn('Talk about my goals','say','What matters next?','primary')}`;
if(t.status==='ready')content+=`<div class="divider"></div><div class="row"><span class="small muted">Not the right moment?</span>${btn('Remind me tomorrow','snooze',id,'small ghost')}</div>`;
showModal(t.title,content);}
function openMoney(){const difference=state.available-state.essential;showModal('Some breathing room.',`<p>A view of the numbers you gave me. We can keep this practical.</p><div class="three-col" style="margin:20px 0"><div class="metric"><span class="small">Available</span><div class="amount">${cash(state.available)}</div></div><div class="metric"><span class="small">Known commitments</span><div class="amount">${cash(state.essential)}</div></div><div class="metric"><span class="small">Difference</span><div class="amount">${cash(difference)}</div></div></div><div class="notice">This excludes anything you have not recorded. It is not a bank balance check or a recommendation to spend the difference.</div><div class="benefit"><h3>${state.income==='late'?'Keep new commitments flexible.':'Keep the essentials visible.'}</h3><p>${state.income==='late'?'While the expected payment is outstanding, check accommodation continuity and unavoidable costs before optional activities.':'Record upcoming accommodation, transport and other commitments before making a larger decision.'}</p></div><div class="actions">${btn('Update my numbers','nav','essentials','primary')}${btn('I’ve reviewed this','complete','budget','ghost')}</div>`,true);}
function openWellbeing(){showModal('A little space for you.',`<p>${state.style==='Direct'?'Let’s make support practical.':'You don’t have to have the perfect words. We can start with what would make this week feel more manageable.'}</p><div class="notice">Based on what you told your companion. No diagnosis, clinical assessment or emergency support is provided by this prototype.</div><div class="section-head"><h3>Support that fits your life</h3></div><div class="form-grid"><div class="card"><span class="small muted">Around your work</span><h3 style="margin-top:8px">${esc(state.hours)}</h3><p>Look for times outside these hours, or a time you can genuinely protect.</p></div><div class="card"><span class="small muted">Your preferred budget</span><h3 style="margin-top:8px">${cash(state.wellbeingBudget)}</h3><p>A search preference, not a verified session price or availability.</p></div></div><div class="benefit"><h3>Check coverage first</h3><p>Ask your insurer or employer assistance programme what support is covered and which providers are included. Share only what is needed for that enquiry.</p></div><div class="benefit"><h3>Find qualified support</h3><p>Use official healthcare resources to find providers, then confirm their specialty, licence, cost, language and appointment times directly.</p><div class="actions"><a class="button" href="https://www.doh.gov.ae/en/resources/Lists%20and%20Tools" target="_blank" rel="noopener noreferrer">Open DoH resources</a>${btn('Prepare my questions','draft','wellbeing','ghost')}</div></div><div class="benefit"><h3>A small human connection</h3><p>A familiar person or a low-pressure activity can be a first step toward feeling connected. It does not replace professional care when needed.</p>${btn('Explore a gentle idea','nav','discover','small ghost')}</div><div class="actions">${btn('Save this next step','wellbeing-save','','primary')}${btn('Not today','wellbeing-later','','ghost')}</div><p class="fine">No provider matching, live prices or booking connection is claimed. You decide what support to pursue.</p>`);}
function draft(kind){let title,text;if(kind==='salary'){title='A calm salary follow-up';text=`Hello, could you please confirm the status of my salary expected on ${fmt(state.salaryDate)} and the anticipated payment date? I’m planning my upcoming commitments and would appreciate an update. Thank you.`;}else if(kind==='housing'){title='A little continuity for your stay';text=`Hello, my current stay ends on ${fmt(state.homeEnd)}. Could you confirm whether an extension is available, the total cost, and the cancellation terms? I’d like to review the options before confirming. Thank you.`;}else if(kind==='medical'){title='A friendly appointment check-in';text='Hello, could you please confirm whether my appointment has been booked? If so, please share the date, time, location, reference and anything I need to bring. Thank you.';}else{title='Questions for a support provider';text=`Hello, I’m exploring professional support and would like to ask about your clinician’s qualifications, availability outside my usual working hours (${state.hours}), consultation fees, and insurance coverage. My preferred budget is around ${cash(state.wellbeingBudget)}; please let me know if suitable options are available. Thank you.`;}showModal(title,`<p>Make this sound like you. Nothing is sent from Rab3.</p><div class="field"><label for="draft-text">Your draft</label><textarea id="draft-text" rows="7" maxlength="3000">${esc(state.drafts?.[kind]||text)}</textarea></div><div class="actions">${btn('Copy my draft','copy-draft','','primary')}${btn('Keep it here','save-draft',kind,'ghost')}</div><div class="fine" style="margin-top:15px">Review the recipient and details before sending it yourself.</div>`);}
function memory(){showModal('What I remember.',`<p>You can correct the practical details or change how we get along. No hidden personality score sits behind this view.</p>${[['Your name',state.name],['Your companion',state.buddy],['Your intention',state.intent],['Your conversational style',state.style],['How you said today feels',state.feeling],['Interests you chose',state.interests.join(', ')||'None yet'],['Working hours',state.hours],['Preferred pace',state.pace]].map(([t,v])=>`<div class="memory-item"><span class="small muted">${t}</span><p>${esc(v)}</p><span class="fine">Source: your entry · editable</span></div>`).join('')}<div class="actions">${btn('Correct my details','nav','essentials','primary')}${btn('Change our style','nav','settings','ghost')}</div>`);}
function changes(){showModal('Life changed. Let’s keep up.',`<p>Choose a demonstration update. Watch priorities, conversation and the journey respond together.</p><div class="actions" style="margin-bottom:18px">${btn('Preview a spontaneous check-in','preview-nudge','','primary')}</div><div class="stack">${[['salary-late','My salary hasn’t arrived','Income → accommodation → spending'],['medical-confirmed','My appointment is confirmed','Residency → completed milestone → fewer reminders'],['home-secured','My next stay is arranged','Housing → priorities → more breathing room'],['salary-received','My salary arrived','Income → follow-up closed → review money'],['overwhelmed','Things feel overwhelming','Pace → smaller steps → practical support'],['advance','Move the demo forward one day','Dates → reminders → refreshed priorities']].map(([id,t,sub])=>`<button class="choice" data-action="event" data-arg="${id}"><strong>${t}</strong><small>${sub}</small></button>`).join('')}</div><div class="fine" style="margin-top:18px">All changes are fictional or user-reported. No external service is contacted.</div>`);}
function history(){showModal('How the path has changed.',state.revisions.length?state.revisions.map(r=>`<div class="benefit"><span class="fine">${fmt(r.date)} · ${esc(r.type)}</span><h3 style="margin-top:7px">${esc(r.title)}</h3><p>${esc(r.detail)}</p></div>`).join(''):'<div class="empty"><h3>A fresh chapter.</h3><p>Changes will appear here as you update your circumstances or complete a step.</p></div>');}
function handoff(){showModal('One update. Only the needed details.',`<div class="notice city">Simulated connection. Nothing will be sent to any organisation.</div><div class="benefit"><h3>Recipient</h3><p>Fictional appointment service in this demonstration.</p></div><div class="benefit"><h3>Purpose</h3><p>Request a status update for one appointment reference.</p></div><div class="benefit"><h3>Included</h3><p>Name: ${esc(state.name)}<br>Reference: DEMO-AD-1042</p></div><div class="benefit"><h3>Stays with your companion</h3><p>Our conversation, feelings, income, preferences and goals.</p></div><div class="actions">${btn('Try this simulated connection','handoff-confirm','','primary')}${btn('Keep it separate','close','','ghost')}</div><p class="fine">A real connection would need an approved service interface and enforceable access controls. This example demonstrates the intended boundary.</p>`);}
function about(){showModal('Rab3, honestly.',`<p>A detailed interactive prototype of a personal Abu Dhabi companion. The wider ambition is lifelong support; the demonstration follows the first 90 days.</p><div class="benefit"><h3>Working here</h3><p>Personal naming and tone, device-local profile, date calculations, prioritisation, cross-domain updates, progress history, snoozing, drafts, public resource links, and inspectable sharing simulations.</p></div><div class="benefit"><h3>Demonstrated, not connected</h3><p>Conversation responses follow a finite scenario engine. No live LLM, payroll, banking, government, healthcare or booking system is connected. No background push notifications or voice input is enabled.</p></div><div class="benefit"><h3>Personal information</h3><p>Profile and optional chat memory stay in this browser’s local storage. They are not encrypted account storage or synced across devices. Use fictional details. The site host may process normal access logs, but this app sends no profile or chat payload.</p></div><div class="benefit"><h3>Wellbeing and belonging</h3><p>Psychology-informed design is a proposed approach, not a validated clinical intervention. Rab3 does not diagnose, guarantee happiness or replace professional care.</p></div><div class="benefit"><h3>Wider infrastructure</h3><p>Government adoption, public funding, integrations and production privacy protections are proposals. Official public links are not endorsements or partnerships.</p></div><div class="actions">${btn('Explore the full map','nav','blueprint','primary')}${btn('Walk through the story','tour','','ghost')}</div>`);}
function tour(){showModal('The whole idea, through one life.',`<div class="card accent-body"><span class="eyebrow">The opening thought</span><h2 style="margin:12px 0">“What’s the one thing we always lie to ourselves about?”</h2><p>“I’m fine.”</p><p>Sometimes we mean: “I haven’t had time to work that out.” Rab3 makes the practical next step easier to see, around the person’s circumstances, time and budget.</p><div class="fine">A presentation hook—not a claim that every person is struggling. Wellbeing is one part of the wider life companion.</div></div><p>Start with the umbrella. Then follow one connected part of it.</p>${[['See the full infrastructure','Ten life domains, one shared context, and a deliberate boundary between the companion and city services.'],['Meet your own companion','A name and conversational style you choose. A warm presence that can start a useful conversation.'],['Introduce a change','Report a delayed salary while accommodation ends soon. Watch income, housing and spending priorities connect.'],['Bring in the human side','Say that things feel overwhelming. The plan becomes smaller and support fits the person’s stated time and budget.'],['Inspect the boundary','A simulated appointment handoff shares only a name and reference. Private conversation never enters the receipt.'],['Close the loop','Record the appointment and next stay. Old prompts stop; completed work stays complete.']].map(([t,d],i)=>`<div class="tour-step"><span class="tour-number">${i+1}</span><div><h3>${t}</h3><p>${d}</p></div></div>`).join('')}<div class="actions">${btn('Start with the big picture','nav','blueprint','primary')}${btn('Try the connected change','event','salary-late','ghost')}</div><div class="fine" style="margin-top:15px">The prototype’s limitations are listed in “About this prototype.” Competition preparation rules remain for the team to confirm.</div>`,true);}
function send(text){text=String(text).trim().slice(0,1200);if(!text)return;state.messages.push({role:'user',text});const result=E.respond(state,text);state.messages.push({role:'assistant',text:result.reply,actions:result.actions});state.messages=state.messages.slice(-80);save();closeModal();navigate('chat');}
function captureOnboarding(){const form=document.getElementById('onboarding-form');if(!form)return;const data=new FormData(form);for(const [key,value]of data){if(key==='budget')state[key]=Number(value);else if(!['memory','reminders'].includes(key))state[key]=String(value).trim();}if(setupStep===2){state.memory=data.has('memory');state.reminders=data.has('reminders');}}
function doEvent(kind){const out=E.event(state,kind);if(!out){toast('That update is already recorded.');return;}save();closeModal();render();showModal(out.title,`<p>${esc(out.detail)}</p><div class="form-grid" style="margin:20px 0"><div class="card"><h3>Before</h3>${out.before.map(id=>`<p>${esc(actionLabel(id))}</p>`).join('')}</div><div class="card"><h3>Now</h3>${out.after.map(id=>`<p>${esc(actionLabel(id))}</p>`).join('')}</div></div><div class="notice">The update is recorded as a demonstration or user report. Completed milestones have not been discarded.</div><div class="actions">${btn('See my day','nav','today','primary')}${btn('Open the journey','nav','journey','ghost')}</div>`);}
const actionHandlers={
nav:arg=>{closeModal();navigate(arg);},close:closeModal,about,tour,task:openTask,money:openMoney,memory,history,changes,handoff,draft,
sample:()=>{state.setup=true;state.messages=[{role:'assistant',text:`Hey ${state.name}. I’m ${state.buddy}. I’ve got your first-days picture. Your next stay and appointment are worth sorting first; we’ll leave room for the things that make this city yours.`,actions:['housing','medical']}];save();navigate('today');},
'on-back':()=>{captureOnboarding();setupStep=Math.max(0,setupStep-1);render();},style:arg=>{captureOnboarding();state.style=arg;render();},say:send,event:doEvent,
'chat-action':arg=>{if(['discover','sharing','city'].includes(arg))navigate(arg);else if(arg==='money')openMoney();else openTask(arg);},
pause:()=>{state.paused=!state.paused;E.addLog(state,'pace',state.paused?'A little space.':'Check-ins are back.',state.paused?'Proactive check-ins paused by you. Direct conversation stays available.':'Useful check-ins can return within your chosen rhythm.');save();render();toast(state.paused?'I’ll give you some space.':'We’ll keep it useful.');},
feeling:arg=>{if(arg==='Overwhelmed')E.event(state,'overwhelmed');else{state.feeling=arg;if(arg==='Need space')state.paused=true;E.addLog(state,'feeling','Today, in your words.',`You chose “${arg}”. This is a self-report, not a clinical assessment.`);}save();render();toast(arg==='Overwhelmed'?'A smaller day. One thing at a time.':'Got it. We’ll take today at your pace.');},
snooze:id=>{state.snoozed[id]=state.day+1;E.addLog(state,'snooze','Not now is okay.',`${E.tasks(state).find(t=>t.id===id)?.title||id} is paused until the next demonstration day.`);save();closeModal();render();toast('We’ll return to this tomorrow.');},
complete:id=>{if(!state.complete.includes(id))state.complete.push(id);E.addLog(state,'progress','A step forward.',`${E.tasks(state).find(t=>t.id===id)?.title||id}: completion recorded by you.`);save();closeModal();render();toast('Recorded. The next step can take its place.');},
interest:x=>{state.interests=state.interests.includes(x)?state.interests.filter(i=>i!==x):[...state.interests,x];save();render();},
'save-idea':id=>{state.saved=state.saved.includes(id)?state.saved.filter(i=>i!==id):[...state.saved,id];save();render();toast(state.saved.includes(id)?'Kept for another day.':'Removed from your saved ideas.');},
'copy-draft':async()=>{const text=document.getElementById('draft-text')?.value||'';try{await navigator.clipboard.writeText(text);toast('Copied. Review it before sending.');}catch{const area=document.getElementById('draft-text');area.focus();area.select();toast('Select and copy the draft from here.');}},
'save-draft':kind=>{state.drafts={...(state.drafts||{}),[kind]:document.getElementById('draft-text').value};E.addLog(state,'draft','A draft, ready when you are.',`Saved ${kind} follow-up on this device. Nothing was sent.`);save();toast('Draft kept on this device. Nothing sent.');},
'wellbeing-save':()=>{state.wellbeing=true;E.addLog(state,'support','Space for support.',`Support exploration saved around ${state.hours} and a preferred budget of ${cash(state.wellbeingBudget)}. No appointment booked.`);save();closeModal();render();toast('Kept in your journey. We can take it slowly.');},
'wellbeing-later':()=>{state.snoozed.wellbeing=state.day+2;save();closeModal();render();toast('No pressure. We’ll leave this quiet for now.');},
'clear-chat':()=>showModal('Clear our conversation?',`<p>This removes the saved chat messages from this browser. Your practical details and journey remain.</p><div class="actions">${btn('Clear conversation','clear-chat-confirm','','danger')}${btn('Keep it','close','','ghost')}</div>`),
'clear-chat-confirm':()=>{state.messages=[];save();closeModal();render();toast('Conversation cleared from this browser.');},
'reset-confirm':()=>showModal('Begin a fresh chapter?',`<p>This deletes this browser’s Rab3 demonstration profile, conversation, progress, drafts and simulated sharing receipts. It does not affect any external service.</p><div class="actions">${btn('Clear and start again','reset','','danger')}${btn('Keep my chapter','close','','ghost')}</div>`),
reset:()=>{localStorage.removeItem(KEY);state=E.fresh();setupStep=0;closeModal();page='today';location.hash='';render();},
'handoff-confirm':()=>{const id='receipt-'+Date.now();state.receipts.unshift({id,date:E.dateAt(state.day),recipient:'Fictional appointment service',fields:['Name: '+state.name,'Reference: DEMO-AD-1042'],disconnected:false});state.connections.appointment=true;E.addLog(state,'sharing','A narrow handoff, demonstrated.','Only name and a fictional appointment reference were staged. Nothing was sent externally.');save();showModal('A receipt you can inspect.',`<div class="notice city">Simulation complete. No data left this browser.</div><p>The simulated recipient received only a name and reference. Your personal conversation and memory were excluded.</p><div class="actions">${btn('Simulate an appointment update','inbound-update','','primary')}${btn('See the receipt','nav','sharing','ghost')}</div>`);},
'inbound-update':()=>{if(!state.connections.appointment){toast('The simulated connection is disconnected.');return;}if(state.medical==='confirmed'){toast('Appointment already recorded.');return;}state.medical='confirmed';E.addLog(state,'simulated service event','A service update helps your companion.','A fictional appointment confirmation entered the journey. No private memory was shared back.');save();closeModal();render();toast('Simulated appointment update received.');},
disconnect:id=>{const r=state.receipts.find(x=>x.id===id);if(r)r.disconnected=true;state.connections.appointment=state.receipts.some(x=>!x.disconnected);save();render();toast('Future updates disconnected. The receipt stays visible.');},
'map-tab':id=>{mapTab=id;mapSelection=id==='boundaries'?'bridge':id==='prototype'?'screen5':'assistant';render();},
'map-node':id=>{mapSelection=id;render();document.querySelector('.map-detail')?.scrollIntoView({behavior:'smooth',block:'nearest'});},
'map-boundary':()=>{mapTab='boundaries';mapSelection='bridge';navigate('blueprint');},
'preview-nudge':()=>{const t=E.priorities(state)[0];if(!t){toast('There is nothing to nudge about right now.');return;}showModal(`${esc(state.buddy)} checks in.`,`<span class="tag">Check-in preview · quiet hours respected outside this preview</span><p>${esc(t.desc)}</p><p>${state.style==='Direct'?'This is the next thing to sort.':state.style==='Playful'?'Let’s get this one off your mental tab list.':'Let’s give this a little attention, before it becomes a bigger worry.'}</p><div class="actions">${btn('Let’s sort it','nudge-open',t.id,'primary')}${btn('Tomorrow is better','nudge-tomorrow','','ghost')}</div>`);},
'nudge-tomorrow':()=>{state.lastPromptDay=state.day;state.snoozed.proactive=state.day+1;save();closeModal();},
'nudge-open':id=>{state.lastPromptDay=state.day;save();openTask(id);}
};
document.addEventListener('click',e=>{const button=e.target.closest('[data-action]');if(!button)return;const handler=actionHandlers[button.dataset.action];if(handler){e.preventDefault();handler(button.dataset.arg||'');}});
document.addEventListener('submit',e=>{if(e.target.id==='chat-form'){e.preventDefault();send(new FormData(e.target).get('message'));}
if(e.target.id==='onboarding-form'){e.preventDefault();captureOnboarding();if(setupStep<2){setupStep++;render();}else{state.setup=true;state.messages=[{role:'assistant',text:`Hey ${state.name}. I’m ${state.buddy}. We’ll take this new chapter at your pace. I’ll bring useful things up, and you can always tell me “not now.”`,actions:['housing','medical']}];save();navigate('today');}}
if(e.target.id==='essentials-form'){e.preventDefault();const form=new FormData(e.target);for(const [key,v] of form){state[key]=['salary','budget','available','essential','wellbeingBudget'].includes(key)?Math.max(0,Number(v)):String(v).trim();}E.addLog(state,'profile','Our understanding is up to date.','You corrected your practical details. Relevant dates and priorities were recalculated; completed work stays complete.');save();render();toast('Updated. Your journey has adjusted.');}
if(e.target.id==='settings-form'){e.preventDefault();const form=new FormData(e.target);['buddy','style','color','pace','quietStart','quietEnd'].forEach(k=>state[k]=String(form.get(k)||state[k]).trim());state.reminders=form.has('reminders');state.paused=form.has('paused');state.memory=form.has('memory');if(!state.memory)state.messages=[];save();render();toast('That feels more like you.');}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&overlay.innerHTML){closeModal();return;}if(e.key==='Tab'&&overlay.innerHTML){const focusable=[...overlay.querySelectorAll('button,a,input,textarea,select')].filter(x=>!x.disabled);const first=focusable[0],last=focusable[focusable.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}if(e.key==='Enter'&&!e.shiftKey&&e.target.id==='message-input'){e.preventDefault();send(e.target.value);}});
window.addEventListener('hashchange',()=>{const next=location.hash.slice(1)||'today';if(next!==page){page=next;render();}});
function maybeNudge(){if(!state.setup||!state.reminders||state.paused||overlay.innerHTML||page!=='today'||state.lastPromptDay===state.day||(state.snoozed.proactive??-1)>state.day)return;const h=new Date().toLocaleTimeString('en-GB',{timeZone:'Asia/Dubai',hour:'2-digit',minute:'2-digit',hour12:false});const a=state.quietStart,b=state.quietEnd;const quiet=a===b?false:a>b?(h>=a||h<b):(h>=a&&h<b);if(quiet)return;const p=E.priorities(state)[0];if(!p||p.priority<(state.pace==='Gentle'?90:state.pace==='More involved'?60:80))return;state.lastPromptDay=state.day;save();showModal(`${esc(state.buddy)} has a small heads-up.`,`<p>${esc(p.desc)}</p><p>${state.style==='Direct'?'This is worth dealing with next.':state.style==='Playful'?'Let’s get this loose end out of your way.':'Let’s give this a little attention, before it becomes a bigger worry.'}</p><div class="actions">${btn('Let’s sort it','nudge-open',p.id,'primary')}${btn('Tomorrow is better','nudge-tomorrow','','ghost')}</div><p class="fine">A prototype check-in based on your recorded dates. You can change its pace or pause it.</p>`);}
setTimeout(maybeNudge,25000);setInterval(maybeNudge,60000);
if(document.modelContext?.registerTool){const lifecycle=new AbortController();window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});const tools=[{name:'rab3_read_demo_journey',title:'Read the Rab3 demo journey',description:'Read the fictional local journey and next actions. Does not read or export chat text.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute(input){if(!input||typeof input!=='object'||Object.keys(input).length)throw new Error('No parameters accepted');return {date:E.dateAt(state.day),priorities:E.priorities(state).map(({id,title,status})=>({id,title,status})),demo:true};}},{name:'rab3_apply_demo_update',title:'Apply a fictional journey update',description:'Change the device-local demonstration and open an explained plan revision. Never contacts external services.',inputSchema:{type:'object',properties:{event:{type:'string',enum:['salary-late','salary-received','medical-confirmed','home-secured','overwhelmed','advance']}},required:['event'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||Object.keys(input).length!==1||!['salary-late','salary-received','medical-confirmed','home-secured','overwhelmed','advance'].includes(input.event))throw new Error('Invalid demo event');doEvent(input.event);return {applied:input.event,date:E.dateAt(state.day),demo:true};}}];for(const t of tools)try{Promise.resolve(document.modelContext.registerTool(t,{signal:lifecycle.signal})).catch(()=>{});}catch{}}
render();
